package com.lyrashop.audit.controller;import java.util.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import com.lyrashop.audit.dto.AdminAuditLogResponse;import com.lyrashop.audit.service.AdminAuditService;@RestController @RequestMapping("/api/v1/admin/audit-logs") @PreAuthorize("hasRole('ADMIN')") public class AdminAuditController{private final AdminAuditService service;public AdminAuditController(AdminAuditService service){this.service=service;}@GetMapping public List<AdminAuditLogResponse> list(){return service.list();}@GetMapping("/page")public com.lyrashop.common.dto.PageResponse<AdminAuditLogResponse> page(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(required=false)String query,@RequestParam(required=false)String action,@RequestParam(required=false)Integer responseStatus,@RequestParam(defaultValue="createdAt")String sort,@RequestParam(defaultValue="desc")String direction){var result=service.page(query,action,responseStatus,com.lyrashop.common.web.AdminPageable.of(page,size,sort,direction,Set.of("createdAt","action","resourceType","responseStatus"),"createdAt"));return com.lyrashop.common.dto.PageResponse.from(result,result.getContent());}}
